    parent := cmd.Parent()
    parent.PersistentPreRun(parent, args)
    fmt.Println("child setup")
}

root := &cobra.Command{
    Use:              "app",
    PersistentPreRun: say("root setup"),
}

child := &cobra.Command{
    Use:              "child",
    PersistentPreRun: setup,
    Run:              say("running"),
}
root.AddCommand(child)

if err := root.Execute(); err != nil {
    os.Exit(1)
}

