func check(cmd *cobra.Command, _ []string) error {
    if port < 1024 {
        return fmt.Errorf("port %d is low", port)
    }
    return nil
}

root := &cobra.Command{
    Use:          "app",
    SilenceUsage: true,
    PreRunE:      check,
    Run:          say("serving"),
}

root.Flags().IntVar(
    &port, "port", 8080, "listen port",
)

if err := root.Execute(); err != nil {
    os.Exit(1)
}

