package main

import (
    "fmt"
    "os"

    "github.com/spf13/cobra"
)

type hook func(*cobra.Command, []string)

func say(s string) hook {
    return func(*cobra.Command, []string) {
        fmt.Println(s)
    }
}

func main() {
}

func guard(cmd *cobra.Command, _ []string) error {
    if os.Getenv("TOKEN") == "" {
        return fmt.Errorf("TOKEN is not set")
    }
    return nil
}

root := &cobra.Command{
    Use:               "app",
    SilenceUsage:      true,
    PersistentPreRunE: guard,
}

root.AddCommand(&cobra.Command{
    Use: "deploy",
    Run: say("deploying"),
})

if err := root.Execute(); err != nil {
    os.Exit(1)
}

